		output.putPlannedDoubleMetric("plannedOperatorFeedbackWorkQErrorMean", feedback.workQErrorMean());
		output.putPlannedDoubleMetric("plannedOperatorFeedbackWorkQErrorMax", feedback.workQErrorMax());
